document.addEventListener('DOMContentLoaded',()=>{const items=['Praia do Aventureiro','Praia Grande','Praia do Bonfim','Praia da Figueira','Praia da Feiticeira','Praia de Lopes Mendes','Praia do Caxadaço','Praia de Dois Rios','Praia da Longa','Praia Vermelha','Praia Brava','Praia das Goiabas','Praia da Biscaia','Praia do Tanguá','Ilha Grande','Ilha da Gipóia','Ilha Cataguás','Ilha Botinas','Ilha de Itanhangá','Ilha de Jorge Grego','Lagoa Azul','Lagoa Verde','Cachoeira da Feiticeira','Pico do Papagaio','Pico da Pedra D’Água','Pico do Frade','Gruta do Acaiá','Farol dos Castelhanos','Passeio de escuna','Vila do Abraão','Vila Histórica de Mambucaba','Freguesia de Santana','Saco do Céu','Bananal','Parnaioca','Provetá','Centro histórico','Convento do Carmo','Igreja de Santa Luzia','Museu de Arte Sacra','Casa de Cultura Poeta Brasil dos Reis','Cais de Santa Luzia','Colégio Naval','Parque da Cidade','Monumento aos Náufragos do Aquidabã','Ermida do Senhor do Bonfim','Observatório Nuclear','Aqueduto do Saco do Céu'];let i=0;const t=document.querySelector('#title'),c=document.querySelector('#counter');document.querySelectorAll('.actions button').forEach(b=>b.addEventListener('click',()=>{i=(i+1)%items.length;t.textContent=items[i];c.textContent=`${i+1} de ${items.length} lugares`}));});
